a('table',rows=[['Téma','Fejezet és tényleges kezdőoldal'],['Vezetői összefoglaló','4. oldal'],['Rendszerarchitektúra, backend, frontend','A.1: 8. • A.2: 22. • A.3: 39.'],['Akadálymentességi audit','46. oldal'],['Mobil, infrastruktúra, bare-metal referencia','B.1: 56. • B.2: 63. • B.3: 75.'],['Szolgáltatások, DevOps, Git és fejlesztői környezet','C.1: 96. • C.2: 110. • C.3: 122.'],['Adatbázis, integrációk, függőségek, OSS','D.1: 133. • D.2: 140. • D.3: 146. • D.4: 159.'],['Skálázhatóság, csapat, dokumentáltság','E.1: 161. • E.2: 174. • E.3: 178.'],['Tesztek, biztonság, megfigyelhetőség, helyreállítás','F.1: 187. • F.2: 191. • F.3: 198. • F.4: 200.'],['Transzkódolás, élő adás, DRM','G.1: 211. • G.2: 217. • G.3: 225.'],['Élő felirat, több hangsáv/kamera, CDN, hirdetések','G.4: 234. • G.5: 240. • G.6: 245. • G.7: 251.'],['Streaming összefüggések, súlyosság, bizonyítékok','G.8: 258. • G.9: 260. • G.10: 261.'],['Megfelelőségi keret, GDPR, akadálymentesség','H.1: 262. • H.2: 264. • H.3: 274.'],['AVMSD, DSA, egyéb jogi/szerződéses kérdések','H.4: 276. • H.5: 280. • H.6: 283. • H.7: 287.'],['Funkciók, osztályzatok, bizonyítékok','I: 290. • J: 292. • K: 294.'],['Szójegyzék, módszertan, hivatkozott keretek','296-299. oldal'],['Érettségi mátrixok, Top 15, kapacitás','299-309. oldal'],['Architektúra-ábrák függeléke','309-311. oldal']])
